1	// Money helpers for fields stored as integer cents.
2	//
3	// The DB layer (coaches.pricePerHour, Stripe amounts) uses integer cents to
4	// avoid floating-point drift in financial math. UI surfaces use these helpers
5	// so euros↔cents conversion stays consistent and round-trips don't lose
6	// precision.
7	
8	/** Format integer cents as a euro string, e.g. 2550 → "25,50". */
9	export function centsToEuroString(cents: number | null | undefined, locale: string = "lt-LT"): string {
10	  if (cents == null || !Number.isFinite(cents)) return "—";
11	  return (cents / 100).toLocaleString(locale, {
12	    minimumFractionDigits: 2,
13	    maximumFractionDigits: 2,
14	  });
15	}
16	
17	/** Format integer cents as a "25,50 €/val" string suitable for coach price labels. */
18	export function centsToEuroLabel(cents: number | null | undefined): string {
19	  if (cents == null) return "";
20	  return `${centsToEuroString(cents)} €`;
21	}
22	
23	/** Convert a user-typed euro string (e.g. "25,50" or "25.5") to integer cents.
24	 *  Returns null for empty or invalid input. */
25	export function euroStringToCents(input: string | null | undefined): number | null {
26	  if (!input) return null;
27	  const normalized = input.replace(",", ".").trim();
28	  if (!normalized) return null;
29	  const n = Number(normalized);
30	  if (!Number.isFinite(n) || n < 0) return null;
31	  return Math.round(n * 100);
32	}
