58	// Navigation-only role switcher. Roles are additive in this system — clicking
59	// "Savininkas" just routes to /owner; it does not change the user's primary
60	// role. Only options the user actually has access to are shown.
61	function RoleSwitcher() {
62	  const [, navigate] = useLocation();
63	  const { isCoach, isOwner } = useRole();
64	  const [open, setOpen] = useState(false);
65	
66	  const options: Array<{ label: string; href: string }> = [];
67	  options.push({ label: "Žaidėjas", href: "/" });
68	  if (isOwner) options.push({ label: "Savininkas", href: "/owner" });
69	  if (isCoach) options.push({ label: "Treneris", href: "/coach/dashboard" });
70	
71	  if (options.length < 2) return null;
72	
73	  return (
74	    <div className="relative">
75	      <button
76	        type="button"
77	        onClick={() => setOpen((o) => !o)}
78	        className="w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm font-medium bg-muted/40 hover:bg-muted transition-colors"
79	      >
80	        <span className="flex items-center gap-2">
81	          <span className="text-[10px] text-muted-foreground uppercase tracking-widest font-semibold">
82	            Rodinys
83	          </span>
84	          <span>Treneris</span>
85	        </span>
86	        <ChevronDown className={`h-3.5 w-3.5 transition-transform ${open ? "rotate-180" : ""}`} />
87	      </button>
88	      {open && (
89	        <div className="absolute left-0 right-0 mt-1 z-10 rounded-lg border bg-card shadow-md overflow-hidden">
90	          {options.map((opt) => (
91	            <button
92	              key={opt.label}
93	              type="button"
94	              onClick={() => {
95	                setOpen(false);
96	                navigate(opt.href);
97	              }}
98	              className="w-full text-left px-3 py-2 text-sm hover:bg-muted transition-colors"
99	            >
100	              {opt.label}
101	            </button>
102	          ))}
103	        </div>
104	      )}
105	    </div>
106	  );
107	}
