28	export function useFacilityId(): number | undefined {
29	  const [location] = useLocation();
30	  return useMemo(() => {
31	    if (typeof window === "undefined") return undefined;
32	    const v = new URLSearchParams(window.location.search).get("facility");
33	    return v ? Number(v) : undefined;
34	  }, [location]);
35	}
