205	function FacilitySidebar({ open, onClose, facilityId, facilityName }: FacilitySidebarProps) {
206	  const [location, navigate] = useLocation();
207	  const items = buildFacilityNavItems(facilityId);
208	
209	  const { data: facilities } = useQuery<FacilityWithCourts[]>({
210	    queryKey: ["owner-facilities"],
211	    queryFn: () => customFetch<FacilityWithCourts[]>(`${API_URL}/facilities`),
212	    enabled: !!facilityId,
213	    staleTime: 60_000,
214	  });
215	
216	  // Unread facility-message count. We deliberately count only message-type
217	  // notifications routed at /owner/ (set by routes/messages.ts when a player
218	  // contacts a court owner) — personal DMs land at /messages and are
219	  // intentionally excluded from this badge.
220	  const { data: facilityUnread = 0 } = useQuery<number>({
221	    queryKey: ["owner-facility-msg-unread"],
222	    queryFn: async () => {
223	      const notifs = await customFetch<Array<{
224	        type: string;
225	        read: boolean;
226	        link: string | null;
227	      }>>(`${API_URL}/notifications?limit=200`);
228	      return notifs.filter(n =>
229	        n.type === "message" &&
230	        !n.read &&
231	        (n.link?.startsWith("/owner/") ?? false),
232	      ).length;
233	    },
234	    staleTime: 30_000,
235	    refetchInterval: 60_000,
236	  });
237	
238	  for (const item of items) {
239	    if (item.label === "Žinutės") item.badge = facilityUnread;
240	  }
241	
242	  const facilityCourts: Court[] = facilityId
243	    ? (facilities?.find((f) => f.id === facilityId)?.courts ?? [])
