273	            e.preventDefault();
274	            onNavigate("/owner");
275	          }}
276	          className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium text-red-600 hover:bg-red-600 hover:text-white transition-colors w-full"
277	        >
278	          <ArrowLeft className="h-4 w-4 shrink-0" />
279	          Grįžti į objektus
280	        </a>
281	      </div>
282	      <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-0.5">
283	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest px-3 pb-2">
284	          Valdymas
285	        </p>
286	
287	        <NavLink item={suvestine} active={suvestine.match(location)} onNavigate={onNavigate} />
288	
