50	  const link = n.link ?? "";
51	  if (link.startsWith("/owner")) return "owner";
52	  if (link.startsWith("/coach")) return "coach";
53	  if (OWNER_TYPE_SET.has(n.type)) return "owner";
54	  if (COACH_TYPE_SET.has(n.type)) return "coach";
55	  return "player";
56	}
