function formatPresence(presence: { online: boolean; lastSeen: string } | undefined): string | null {
  if (!presence) return null;
  if (presence.online) return "dabar prisijungęs(-usi)";
  const lastSeen = new Date(presence.lastSeen);
  if (lastSeen.getTime() === 0) return null;
  const diff = Date.now() - lastSeen.getTime();
  const min = Math.floor(diff / 60_000);
  if (min < 2) return "ką tik buvo";
  if (min < 60) return `buvo prieš ${min} min.`;
  const h = Math.floor(min / 60);
  if (h < 24) return `buvo prieš ${h} val.`;
  const d = Math.floor(h / 24);
  if (d < 7) return `buvo prieš ${d} d.`;
  return lastSeen.toLocaleDateString("lt-LT", { month: "short", day: "numeric" });

