65	export function initSocketIO(httpServer: HttpServer): SocketIOServer {
66	  io = new SocketIOServer(httpServer, {
67	    cors: { origin: true, credentials: true },
68	    transports: ["websocket", "polling"],
69	  });
70	
71	  // Auth middleware — runs before "connection" fires
72	  io.use(async (socket, next) => {
73	    try {
74	      const token = socket.handshake.auth?.token as string | undefined;
75	      const userId = socket.handshake.auth?.userId as string | undefined;
76	
77	      // Agent bypass (dev / automated tests)
78	      const bypassKey = process.env.AGENT_BYPASS_KEY;
79	      if (bypassKey && socket.handshake.auth?.agentKey === bypassKey) {
80	        socket.data.userId = userId ?? "agent-test-user";
81	        return next();
82	      }
83	
84	      // No Clerk secret in dev → trust the userId from the handshake
85	      if (!process.env.CLERK_SECRET_KEY) {
86	        socket.data.userId = userId ?? "anon";
87	        return next();
88	      }
89	
90	      if (!token) return next(new Error("auth:no_token"));
91	
92	      // clerkClient.verifyToken is available on @clerk/express v2+
93	      const payload = await (clerkClient as any).verifyToken(token) as { sub: string };
94	      socket.data.userId = payload.sub;
95	      next();
96	    } catch {
97	      next(new Error("auth:invalid_token"));
98	    }
99	  });
100	
101	  io.on("connection", (socket) => {
102	    const userId: string = socket.data.userId;
103	
104	    // Every authenticated user is always subscribed to their own inbox room
105	    // so that unread_update events reach them regardless of which chat is open.
106	    socket.join(`inbox_${userId}`);
107	    presenceMap.set(userId, { lastSeen: new Date(), online: true });
108	    logger.debug({ userId, id: socket.id }, "socket connected");
109	
110	    // Clients emit this whenever they open a specific conversation.
111	    // The server adds the socket to the appropriate narrow room so future
112	    // new_message events are only delivered to sockets that care about them.
113	    //
114	    // Authorization note: DM rooms are accidentally safe because the room
115	    // name is derived from the *joining* user's pair, so an eavesdropper
116	    // ends up in a different room from the actual conversation. Facility
117	    // and game rooms have shared room names, so we must verify ownership /
118	    // participation before joining; otherwise any authenticated user could
119	    // listen in on any conversation by guessing IDs.
120	    socket.on("join_rooms", async (params: {
121	      dmUserId?: string;
122	      courtId?: number;
123	      playerId?: string;
124	      gameId?: number;
125	    }) => {
126	      try {
127	        if (params.dmUserId) {
128	          socket.join(dmRoom(userId, params.dmUserId));
129	        }
130	        if (params.courtId != null && params.playerId) {
131	          const allowed = await canJoinFacilityRoom(userId, params.courtId, params.playerId);
132	          if (allowed) {
133	            socket.join(`facility_${params.courtId}_${params.playerId}`);
134	          } else {
135	            logger.warn(
136	              { userId, courtId: params.courtId, playerId: params.playerId },
137	              "socket facility room join denied",
138	            );
139	          }
140	        }
141	        if (params.gameId != null) {
142	          const allowed = await canJoinGameRoom(userId, params.gameId);
143	          if (allowed) {
144	            socket.join(`game_${params.gameId}`);
145	          } else {
146	            logger.warn(
147	              { userId, gameId: params.gameId },
148	              "socket game room join denied",
149	            );
150	          }
151	        }
152	      } catch (err) {
153	        logger.error({ err, userId }, "socket join_rooms failed");
154	      }
155	    });
156	
157	    socket.on("leave_rooms", (params: {
158	      dmUserId?: string;
159	      courtId?: number;
160	      playerId?: string;
161	      gameId?: number;
162	    }) => {
163	      if (params.dmUserId) {
164	        socket.leave(dmRoom(userId, params.dmUserId));
165	      }
166	      if (params.courtId != null && params.playerId) {
167	        socket.leave(`facility_${params.courtId}_${params.playerId}`);
168	      }
169	      if (params.gameId != null) {
170	        socket.leave(`game_${params.gameId}`);
171	      }
172	    });
173	
174	    socket.on("disconnect", () => {
175	      // Only mark offline if this was the user's last socket
176	      const remaining = io?.sockets.sockets;
177	      const stillOnline = remaining
178	        ? [...remaining.values()].some(s => s !== socket && s.data.userId === userId)
179	        : false;
180	      if (!stillOnline) presenceMap.set(userId, { lastSeen: new Date(), online: false });
181	      logger.debug({ userId, id: socket.id }, "socket disconnected");
182	    });
183	  });
184	
185	  return io;
186	}
